INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(44509898, 'Pinpoint Guard', '精确防御', 'ピンポイント・ガード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击宣言时，以自己墓地1只4星以下的怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在这个回合不会被战斗·效果破坏。'),
(17322533, 'Pinpoint Landing', '一点着地', '一点着地', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：只让怪兽1只特殊召唤的场合，若那是从自己或对方的手卡往自己场上的特殊召唤则能发动。自己抽1张。 ②：自己回合没因这张卡的①的效果抽卡的场合，那个回合的结束阶段这张卡送去墓地。'),
(50823978, 'Piranha Army', '军队食人鱼', '軍隊ピラニア', 'Effect Monster', 'Fish', 'WATER', 2, 800, 200, '这张卡对对方进行直接攻击时战斗伤害加倍。'),
(33907039, 'Piri Reis Map', '皮瑞雷斯的地图', 'ピリ・レイスの地図', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己主要阶段1开始时才能发动。从卡组把1只攻击力0的怪兽加入手卡，自己基本分变成一半。这张卡的发动后，直到下个回合的结束时，自己只要这个效果加入手卡的怪兽或者那些同名卡的召唤不成功，不能把那只怪兽以及那些同名卡的效果发动。'),
(34029630, 'Pitch-Black Power Stone', '漆黑的能量石', '漆黒のパワーストーン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡发动的场合，给这张卡放置3个魔力指示物来发动。 ①：自己回合1次，以这张卡以外的场上1张可以放置魔力指示物的卡为对象才能发动。这张卡1个魔力指示物取除，给那张卡放置1个魔力指示物。 ②：这张卡的魔力指示物全部被取除的场合这张卡破坏。'),
(88975532, 'Pitch-Black Warwolf', '漆黑战士 战狼', '漆黒の戦士 ワーウルフ', 'Effect Monster', 'Beast-Warrior', 'DARK', 4, 1600, 600, '①：只要这张卡在怪兽区域存在，对方在战斗阶段不能把陷阱卡发动。'),
(47415292, 'Pitch-Dark Dragon', '漆黑的斗龙', '漆黒の闘龍', 'Union Effect Monster', 'Dragon', 'DARK', 3, 900, 600, '1回合只有1次在自己的主要阶段可以当作装备卡使用给自己的「暗魔界的战士 暗黑之剑」装备，或者把装备解除以表侧攻击表示特殊召唤。只在这个效果当作装备卡使用时，装备怪兽的攻击力·守备力上升400点。装备怪兽攻击守备表示的怪兽时，若攻击力超过那个守备力，给与对方那个数值的战斗伤害。（1只怪兽可以装备的同盟最多1张。装备怪兽被战斗破坏的场合，作为代替把这张卡破坏。）'),
(47759571, 'Pitknight Earlie', '维修站骑士・厄莉', 'ピットナイト・アーリィ', 'Link Monster', 'Cyberse', 'FIRE', NULL, 1500, NULL, '效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡所连接区的怪兽把效果发动时，以对方场上1只效果怪兽为对象才能发动。那只怪兽直到回合结束时攻击力变成0，效果无效化。 ②：这张卡被战斗·效果破坏送去墓地的回合的结束阶段才能发动。这张卡特殊召唤。'),
(25919316, 'Pitknight Filly', '维修站骑士・菲儿', 'ピットナイト・フィル', 'Link Monster', 'Cyberse', 'FIRE', NULL, 1500, NULL, '效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在连接怪兽所连接区特殊召唤的场合，以自己场上1只攻击力1500以下的怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击，那只怪兽用和对方怪兽的战斗给与对方的战斗伤害变成2倍。 ②：这张卡被战斗·效果破坏送去墓地的场合，下个回合的准备阶段才能发动。这张卡从墓地特殊召唤。'),
(83682209, 'Piwraithe the Ghost Pirate', '海灵贼', '海霊賊', 'Effect Monster', 'Aqua', 'WATER', 4, 1500, 500, '这个卡名的效果1回合只能使用1次。 ①：这张卡在墓地存在的状态，「海灵贼」以外的自己场上的表侧表示的水属性怪兽被战斗·效果破坏的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡的攻击力直到下个回合的结束时上升自己墓地的水属性怪兽数量×100。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(35429292, 'Pixie Knight', '妖精骑士', 'ピクシーナイト', 'Effect Monster', 'Spellcaster', 'LIGHT', 2, 1300, 200, '这张卡被战斗破坏送去墓地时，由对方选择自己墓地里的1张魔法卡，放在自己卡组的最上面。'),
(46502013, 'Pixie Ring', '妖精轮', 'ガリトラップ－ピクシーの輪－', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '自己场上有怪兽表侧攻击表示2只以上存在的场合，对方不能选择攻击力最低的怪兽作为攻击对象。'),
(55696885, 'Plague Wolf', '疫病狼', '疫病狼', 'Effect Monster', 'Zombie', 'DARK', 3, 1000, 1000, '①：1回合1次，自己主要阶段才能发动。这张卡的攻击力直到回合结束时变成原本攻击力的2倍。 ②：这张卡的①的效果发动的场合，结束阶段发动。这张卡破坏。'),
(33420078, 'Plaguespreader Zombie', '僵尸带菌者', 'ゾンビキャリア', 'Tuner Monster', 'Zombie', 'DARK', 2, 400, 200, '①：这张卡在墓地存在的场合，让1张手卡回到卡组最上面才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(10282757, 'Planckton', '浮朗克尺度', 'プランクスケール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：这个回合中，以下效果适用。 ●双方场上的全部3阶以下的超量怪兽的攻击力·守备力上升500。 ●双方场上的全部4阶以上的超量怪兽不能攻击。'),
(97526666, 'Planet Pathfinder', '行星探查车', '惑星探査車', 'Effect Monster', 'Machine', 'EARTH', 4, 1000, 1000, '①：把这张卡解放才能发动。从卡组把1张场地魔法卡加入手卡。'),
(39163598, 'Planet Pollutant Virus', '惑星污染病毒', '惑星汚染ウイルス', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上存在的1只名字带有「外星」的怪兽解放发动。对方场上表侧表示存在的没有A指示物放置的怪兽全部破坏。用对方回合计算的3回合内对方召唤、反转召唤、特殊召唤的怪兽全部放置1个A指示物。'),
(54451023, 'Plant Food Chain', '植物链', '植物連鎖', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成攻击力上升500的装备卡，给自己场上存在的1只植物族怪兽装备。变成装备卡的这张卡被其他卡的效果破坏的场合，可以选择自己墓地存在的1只植物族怪兽特殊召唤。'),
(28062326, 'Plant Token', '竹头木屑', '竹頭木屑', 'Token', 'Plant', NULL, NULL, NULL, NULL, NULL),
(92595545, 'Plasma Ball', '等离子球', 'プラズマ・ボール', 'Effect Monster', 'Thunder', 'LIGHT', 3, 900, 900, '这张卡可以直接攻击对方玩家。这张卡直接攻击给与对方基本分战斗伤害时，这张卡破坏。'),
(40216089, 'Platinum Gadget', '白金小工具', 'プラチナ・ガジェット', 'Link Monster', 'Machine', 'LIGHT', NULL, 1600, NULL, '机械族怪兽2只 这个卡名的①②的效果1回合各能使用1次。这张卡在连接召唤的回合不能作为连接素材。 ①：自己主要阶段才能发动。从手卡把1只4星以下的机械族怪兽在作为这张卡所连接区的自己场上特殊召唤。 ②：这张卡被战斗·效果破坏的场合才能发动。从卡组把1只4星「零件」怪兽特殊召唤。'),
(13070280, 'Play of the Tistina', '提斯蒂娜的嬉戏', 'ティスティナの戯れ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己的手卡·墓地把1只「提斯蒂娜」怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽在结束阶段回到手卡。'),
(39881252, 'Play the Diabell', '兴妖迪亚贝尔', 'プレイ・ザ・ディアベル', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：魔法·陷阱卡为让卡的效果发动而被送去墓地的场合才能发动。从手卡·卡组·额外卡组把1只幻想魔族·魔法师族怪兽送去墓地。 ②：自己主要阶段，从自己墓地把包含这张卡的3张魔法·陷阱卡除外才能发动。从自己的手卡·墓地把1只「迪亚贝尔」怪兽特殊召唤。'),
(69529567, 'Playful Possum', '装傻负鼠', 'おとぼけオポッサム', 'Effect Monster', 'Beast', 'EARTH', 2, 800, 600, '自己的主要阶段时，持有比这张卡的攻击力高的攻击力的怪兽在对方场上表侧表示存在的场合，可以把场上存在的这张卡破坏。此外，自己的准备阶段时，这张卡的效果破坏的这张卡可以从墓地特殊召唤。'),
(20426176, 'Plunder Patroll Booty', '海造贼-大航海', '海造賊－大航海', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次。 ①：宣言1个属性，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时变成宣言的属性。那之后，可以从自己墓地选1只「海造贼」怪兽回到卡组或特殊召唤。 ②：自己·对方的结束阶段，「海造贼」怪兽不在自己场上存在的场合发动。这张卡送去墓地。'),
(43004235, 'Plunder Patroll Parrrty', '海造贼-祝宴', '海造賊－祝宴', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①的效果1回合只能使用1次，②的效果在决斗中只能使用1次。 ①：自己场上有「海造贼」怪兽存在的场合才能把这张卡发动。自己从卡组抽出自己场上的装备卡的数量＋1张，那之后手卡选自己场上的装备卡的数量回到卡组。 ②：这张卡在墓地存在，自己从额外卡组把「海造贼」怪兽特殊召唤的场合才能发动。这张卡给那1只怪兽当作攻击力上升500的装备卡使用来装备。'),
(44227727, 'Plunder Patroll Shipshape Ships Shipping', '海造贼-进水式', '海造賊－進水式', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：从自己的手卡·场上把恶魔族融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。 ②：把墓地的这张卡除外，以自己场上1只「海造贼」怪兽为对象才能发动。那只自己怪兽从卡组把1张「海造贼-象征」装备或从卡组把1只「海造贼」怪兽当作装备卡使用来装备。'),
(93031067, 'Plunder Patroll Shipyarrrd', '海造贼-据点', '海造賊－拠点', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的②③的效果1回合各能使用1次。 ①：自己场上的「海造贼」怪兽的攻击力上升自己的魔法与陷阱区域的「海造贼」卡数量×500。 ②：自己主要阶段，丢弃1张手卡才能发动。从卡组把「海造贼-据点」以外的1张「海造贼」卡加入手卡。 ③：这张卡在墓地存在的场合，以自己的魔法与陷阱区域1张「海造贼」卡为对象才能发动。这张卡在自己场上盖放，作为对象的卡回到持有者手卡。'),
(94253655, 'Plunder Patrollship Brann', '海造贼-豪速之烈火号', '海造賊－豪速のブレンネ号', 'Synchro Monster', 'Fiend', 'FIRE', 8, 2500, 1000, '调整＋调整以外的怪兽1只以上 这个卡名的②的效果1回合只能使用1次。 ①：自己场上的其他的恶魔族怪兽的攻击力上升500。 ②：从手卡丢弃1张「海造贼」卡，以对方场上1张魔法·陷阱卡为对象才能发动。那张卡除外。那之后，可以从卡组把1只「海造贼」怪兽加入手卡。这张卡有「海造贼」卡装备的场合，这个效果在对方回合也能发动。'),
(85969517, 'Plunder Patrollship Jord', '海造贼-庄重之大地号', '海造賊－荘重のヨルズ号', 'Synchro Pendulum Effect Monster', 'Fiend', 'EARTH', 8, 1500, 3000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的怪兽效果1回合各能使用1次。 ①：对方对怪兽的特殊召唤成功的场合才能发动。从卡组把1张「海造贼」卡加入手卡。这张卡有「海造贼」卡装备的场合，可以再从卡组把1只「海造贼」怪兽特殊召唤。 ②：以自己墓地1张「海造贼」卡为对象才能发动。那张卡加入手卡，这张卡在自己的灵摆区域放置。'),
(18832779, 'Plunder Patrollship Lys', '海造贼-双翼之光照号', '海造賊－双翼のリュース号', 'Fusion Monster', 'Fiend', 'LIGHT', 8, 2000, 2000, '「海造贼」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。从手卡以及自己的魔法与陷阱区域的表侧表示的卡之中选1张「海造贼」怪兽卡特殊召唤。 ②：对方把怪兽的效果发动时，从手卡丢弃1张「海造贼」卡才能发动。那个发动无效并破坏。这张卡有「海造贼」卡装备的场合，可以再从卡组把1张「海造贼」卡加入手卡。'),
(20248754, 'Plunder Patrollship Moerk', '海造贼-静寂之暗夜号', '海造賊－静寂のメルケ号', 'XYZ Monster', 'Fiend', 'DARK', 4, 1000, 2500, '4星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：从手卡丢弃1张「海造贼」卡，以对方场上1只效果怪兽为对象才能发动。那只怪兽除外。那之后，可以从卡组把1张「海造贼」魔法·陷阱卡加入手卡。这张卡有「海造贼」卡装备的场合，这个效果在对方回合也能发动。 ②：自己场上的「海造贼」卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(89016236, 'Poeltis de Nouvelles', '生煎之布娃雷提斯・饿魔新飨', 'ポワレティス・ド・ヌーベルズ', 'Ritual Effect Monster', 'Beast-Warrior', 'DARK', 3, 1200, 1850, '「食谱」卡降临。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。自己从卡组抽1张。 ②：场上的怪兽成为攻击·效果的对象时才能发动。自己场上1只「新式魔厨」怪兽和自己·对方场上1只攻击表示怪兽解放，从手卡·卡组把1只4·5星的「新式魔厨」仪式怪兽特殊召唤。'),
(33302407, 'Poison Chain', '剧毒链', 'ポイズン・チェーン', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己回合没有进行战斗的场合，结束阶段时可以把自己场上表侧表示存在的名字带有「链」的怪兽数量的卡从对方卡组上面送去墓地。'),
(56840658, 'Poison Draw Frog', '抽卡青蛙', '引きガエル', 'Effect Monster', 'Aqua', 'WATER', 2, 100, 100, '场上表侧表示的这张卡被送去墓地时，可以从自己卡组抽1张卡。'),
(76539047, 'Poison Fangs', '猛毒之牙', 'ポイズン・ファング', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '兽族怪兽每次给与对方战斗伤害时，给与对方基本分500分的伤害。'),
(43716289, 'Poison Mummy', '剧毒木乃伊', 'ポイズンマミー', 'Flip Effect Monster', 'Zombie', 'EARTH', 4, 1000, 1800, '反转：给与对方500基本分伤害。'),
(8842266, 'Poison of the Old Man', '隐居者的猛毒药', 'ご隠居の猛毒薬', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：可以从以下效果选择1个发动。 ●自己回复1200基本分。 ●给与对方800伤害。'),
(86801872, 'Poisonous Snake Token', '蛇壶', 'スネークポット', 'Token', 'Reptile', NULL, NULL, NULL, NULL, NULL),
(561300, 'Poisonous Viper', '剧毒蝮蛇', '猛毒マムシ', 'Effect Monster', 'Reptile', 'EARTH', 1, 100, 200, '这个卡名的③的效果1回合只能使用1次。 ①：把手卡的这张卡给对方观看才能发动。这张卡特殊召唤。对方场上没有怪兽存在的场合，作为代替在对方场上守备表示特殊召唤。 ②：自己准备阶段发动。自己受到500伤害。 ③：这张卡被除外的场合或者被效果送去墓地的场合，以对方场上1张里侧表示的魔法·陷阱卡为对象才能发动（不能对应这个发动把作为对象的卡发动）。那张卡破坏。'),
(95561280, 'Poisonous Winds', '猛毒之风', '猛毒の風', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '只要这张卡在场上存在，双方不能把风属性怪兽特殊召唤。此外，场上表侧表示存在的全部风属性怪兽的攻击力下降500。'),
(46485778, 'Poissonniere de Nouvelles', '烹鱼大厨・饿魔新飨', 'ポワソニエル・ド・ヌーベルズ', 'Pendulum Effect Monster', 'Fairy', 'DARK', 1, 700, 1700, '这个卡名的①的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，可以从以下效果选择1个发动。 ●把1只1星仪式怪兽或者1张「食谱」卡从卡组加入手卡。 ●从自己墓地把「食谱」卡任意数量除外，把持有和那个数量相同等级的1只「新式魔厨」仪式怪兽从手卡特殊召唤。 ②：场上的这张卡被解放以表侧加入额外卡组的场合才能发动。这张卡在自己的灵摆区域放置。'),
(8175346, 'Poki Draco', '波可哆啦', 'ポケ・ドラ', 'Effect Monster', 'Dragon', 'FIRE', 3, 200, 100, '这张卡召唤成功时，可以从自己卡组把1只「袖珍龙」加入手卡。'),
(73578229, 'Pole Position', '杆位', 'ポールポジション', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '场上表侧表示存在的攻击力最高的怪兽不受魔法的效果影响。场上不存在「杆位」时，场上表侧表示存在的攻击力最高的怪兽破坏。'),
(91078716, 'Pollinosis', '花粉症', 'ポリノシス', 'Trap Card', 'Counter', NULL, NULL, NULL, NULL, '把自己场上存在的1只植物族怪兽解放发动。魔法·陷阱卡的发动、怪兽的召唤·特殊召唤的其中1个无效并破坏。'),
(44088292, 'Poly-Chemicritter Dioxogre', '进化合兽 二氧鬼神', '進化合獣ダイオーキシン', 'Gemini Monster', 'Fiend', 'DARK', 8, 2800, 200, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●只要这张卡在怪兽区域存在，二重怪兽的召唤不会被无效化。 ●1回合1次，把自己墓地1只二重怪兽除外，以对方场上1张卡为对象才能发动。那张卡破坏。'),
(80476891, 'Poly-Chemicritter Hydragon', '进化合兽 水蛇龙', '進化合獣ヒュードラゴン', 'Gemini Monster', 'Dragon', 'WATER', 8, 200, 2800, '①：这张卡只要在场上·墓地存在，当作通常怪兽使用。 ②：可以把场上的当作通常怪兽使用的这张卡作为通常召唤作再1次召唤。那个场合这张卡变成当作效果怪兽使用并得到以下效果。 ●这张卡以外的二重怪兽召唤成功时才能发动。那只怪兽的攻击力·守备力上升500。 ●自己场上的二重怪兽被效果破坏的场合，可以作为代替把自己场上1张卡破坏。'),
(24094653, 'Polymerization', '融合', '融合', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的手卡·场上的怪兽作为融合素材，把1只融合怪兽融合召唤。'),
(15248873, 'Pop-Up', '弹出式翻页', 'ポップルアップ', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '「弹出式翻页」在1回合只能发动1张。 ①：对方的场地区域有卡存在，自己的场地区域没有卡存在的场合才能发动。从卡组把1张场地魔法卡发动。'),
(5800323, 'Poplar of the White Forest', '白森的幻妖', '白き森の幻妖', 'Synchro Tuner Monster', 'Illusion', 'LIGHT', 4, 700, 2000, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以自己墓地2只「白森林」怪兽为对象才能发动。那些怪兽当作永续魔法卡使用在原本持有者的魔法与陷阱区域表侧表示放置。 ②：对方主要阶段才能发动。用包含这张卡的自己场上的怪兽为素材进行同调召唤。'),
(61840587, 'Portable Battery Pack', '携带型电池', '携帯型バッテリー', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '从自己墓地选择2只名字带有「电池人」的怪兽，攻击表示特殊召唤。这张卡从场上离开时，那些怪兽全部破坏。那些怪兽全部从场上离开时这张卡破坏。'),
(25642998, 'Poseidon Wave', '波塞冬之浪', 'ポセイドン・ウェーブ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '对方怪兽的攻击宣言时才能发动。把1只对方怪兽的攻击无效。自己场上有鱼族·海龙族·水族怪兽表侧表示存在的场合，给与对方基本分那个数量×800的数值的伤害。'),
(60517697, 'Poseidra Abyss, the Atlantean Dragon Lord', '海皇龙神 波塞多拉・邃渊', '海皇龍神 ポセイドラ・アビス', 'XYZ Monster', 'Sea Serpent', 'WATER', 7, 3000, 1800, '7星怪兽×3 「海皇龙神 波塞德拉·深渊」1回合1次也能在自己场上的「海皇」超量怪兽或「水精鳞」超量怪兽上面重叠来超量召唤。 ①：1回合1次，把这张卡2个超量素材取除，从手卡·卡组把1只水属性怪兽送去墓地才能发动。对方场上最多3张卡回到手卡。 ②：超量召唤的这张卡被送去墓地的场合，把1张手卡丢弃去墓地才能发动。从自己的手卡·墓地把3只3星以下的鱼族·海龙族·水族怪兽特殊召唤。'),
(47826112, 'Poseidra, the Atlantean Dragon', '海皇龙 波塞多拉', '海皇龍 ポセイドラ', 'Effect Monster', 'Sea Serpent', 'WATER', 7, 2800, 1600, '把自己场上3只3星以下的水属性怪兽解放才能发动。这张卡从手卡或者墓地特殊召唤。这个效果特殊召唤成功时，场上的魔法·陷阱卡全部回到持有者手卡。这个效果让卡3张以上回到手卡的场合，对方场上的全部怪兽的攻击力下降回到手卡的卡数量×300的数值。'),
(99193444, 'Poseidra, the Storming Atlantean', '轰海皇 波塞多拉', '轟海皇 ポセイドラ', 'Effect Monster', 'Sea Serpent', 'WATER', 7, 2800, 1600, '这个卡名的①②的效果1回合各能使用1次。 ①：从自己的手卡·场上（表侧表示）把1只其他的水属性怪兽送去墓地才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合，从卡组把1只「海皇」怪兽或「水精鳞」怪兽送去墓地，以对方场上1张卡为对象才能发动。那张卡回到手卡。 ③：只要自己场上有「轰海皇 波塞德拉」以外的怪兽存在，对方怪兽不能选择这张卡作为攻击对象。'),
(52860176, 'Possessed Dark Soul', '凭依的血魂', '憑依するブラッド・ソウル', 'Effect Monster', 'Fiend', 'DARK', 3, 1200, 800, '这张卡做祭品。得到对方场上的全部3星以下的怪兽的控制权。'),
(65046521, 'Possessed Partnerships', '凭依连携', '憑依連携', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从自己的手卡·墓地把1只守备力1500的魔法师族怪兽表侧攻击表示或里侧守备表示特殊召唤。那之后，自己场上的怪兽的属性是2种类以上的场合，可以把场上1张表侧表示卡破坏。 ②：把墓地的这张卡除外，以自己墓地1张「凭依」永续魔法·永续陷阱卡为对象才能发动。那张卡在自己场上表侧表示放置。'),
(45508030, 'Possessed Resonance', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(64014615, 'Pot of Acquisitiveness', '大欲之壶', '大欲な壺', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从除外的自己以及对方的怪兽之中以合计3只为对象才能发动。那3只怪兽回到持有者卡组洗切。那之后，自己从卡组抽1张。'),
(67169062, 'Pot of Avarice', '贪欲之壶', '貪欲な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以自己墓地5只怪兽为对象才能发动。那5只怪兽回到卡组。那之后，自己抽2张。'),
(51790181, 'Pot of Benevolence', '无欲之壶', '無欲な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：以自己·对方的墓地的卡合计2张为对象才能发动。那些卡回到持有者卡组。这张卡发动后，不送去墓地而除外。'),
(35261759, 'Pot of Desires', '强欲而贪欲之壶', '強欲で貪欲な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从自己卡组上面把10张卡里侧表示除外才能发动。自己从卡组抽2张。'),
(98672567, 'Pot of Dichotomy', '贪欲而无欲之壶', '貪欲で無欲な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这张卡发动的回合，自己不能进行战斗阶段。 ①：自己主要阶段1开始时，以自己墓地3只怪兽为对象才能发动（相同种族最多1只）。那3只怪兽回到卡组洗切。那之后，自己从卡组抽2张。'),
(98645731, 'Pot of Duality', '强欲而谦虚之壶', '強欲で謙虚な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能把怪兽特殊召唤。 ①：从自己卡组上面把3张卡翻开，从那之中选1张加入手卡。那之后，剩下的卡回到卡组。'),
(49238328, 'Pot of Extravagance', '强欲且金满之壶', '強欲で金満な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己主要阶段1开始时，把自己的额外卡组3张或6张里侧的卡随机里侧除外才能发动。除外的卡每有3张，自己抽1张。这张卡的发动后，直到回合结束时自己不能用卡的效果抽卡。'),
(70278545, 'Pot of Generosity', '谦虚之壶', '謙虚な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：选自己2张手卡回到卡组。'),
(55144522, 'Pot of Greed', '强欲之壶', '強欲な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己从卡组抽2张。'),
(84211599, 'Pot of Prosperity', '金满而谦虚之壶', '金満で謙虚な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能用卡的效果抽卡。 ①：从额外卡组把3张或6张卡里侧除外才能发动。把除外数量的卡从自己卡组上面翻开，从那之中选1张加入手卡，剩下的卡用喜欢的顺序回到卡组下面。这张卡的发动后，直到回合结束时对方受到的全部伤害变成一半。'),
(96598015, 'Pot of Riches', '金满之壶', '金満な壺', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这张卡发动的回合，自己不能作灵摆召唤以外的特殊召唤。 ①：从自己的额外卡组的表侧表示的灵摆怪兽以及自己墓地的灵摆怪兽之中选合计3只，回到卡组洗切。那之后，自己从卡组抽2张。'),
(91501248, 'Pot of The Forbidden', '禁忌之壶', '禁忌の壺', 'Flip Effect Monster', 'Rock', 'EARTH', 9, 2000, 3000, '这个卡名的效果1回合只能使用1次。 ①：这张卡反转的场合，可以从以下效果选择1个发动。 ●自己抽2张。 ●场上的魔法·陷阱卡全部回到手卡。 ●对方场上的怪兽全部破坏。 ●把对方手卡确认，选那之内的1张回到卡组。'),
(55567161, 'Pot the Trick', '戏法壶', 'ポット・ザ・トリック', 'Normal Monster', 'Rock', 'EARTH', 2, 400, 400, '根据魔术师的命令行动的使魔。不是很强。'),
(54112932, 'Potato & Chips', '薯薯与片片', 'ポテト＆チップス', 'Normal Monster', 'Plant', 'EARTH', 2, 200, 200, '薯薯和片片总是非常要好。啃着薯片呆在屋里无所事事。法式清汤味也很好吃。海苔盐味也味道不错。薯薯和片片过着美味可口的生活。'),
(89055154, 'Power Angel Valkyria', '力天使 女武神', '力天使ヴァルキリア', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1800, 1050, '这个卡名的效果1回合只能使用1次。 ①：自己把怪兽的效果·魔法·陷阱卡的发动无效的场合发动。从卡组把1只天使族·光属性怪兽加入手卡。'),
(37630732, 'Power Bond', '力量焊接', 'パワー・ボンド', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己的手卡·场上的怪兽作为融合素材，把1只机械族融合怪兽融合召唤。这个效果特殊召唤的怪兽的攻击力上升那个原本攻击力数值。这张卡发动的回合的结束阶段让自己受到这个效果上升的数值的伤害。'),
(300302051, 'Power Bond (Skill Card)', NULL, NULL, 'Skill Card', 'Syrus Truesda', NULL, NULL, NULL, NULL, NULL),
(86821010, 'Power Break', '武力解除', 'パワー・ブレイク', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：自己场上有「动力工具龙」存在的场合，以自己的场上·墓地最多3张装备卡为对象才能发动。那些卡回到持有者卡组，给与对方回去数量×500伤害。'),
(6903857, 'Power Breaker', '强力破坏者', 'パワー・ブレイカー', 'Effect Monster', 'Warrior', 'EARTH', 4, 1900, NULL, '这张卡被对方怪兽的攻击或者对方的效果破坏送去墓地时，选择对方场上表侧表示存在的1张魔法·陷阱卡破坏。这张卡攻击的场合，伤害步骤结束时变成守备表示。'),
(54289683, 'Power Capsule', '能量胶囊', 'パワーカプセル', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只「胜利蛇XX03」发动。从「胜利蛇XX03」的效果选择1个，作为这张卡的效果适用。'),
(19844995, 'Power Filter', '召唤限制-力量过滤器', '召喚制限－パワーフィルター', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '双方玩家不能把攻击力1000以下的怪兽特殊召唤。'),
(53656677, 'Power Frame', '力量框架', 'パワー・フレーム', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '自己场上表侧表示存在的怪兽被选择作为持有比那个攻击力高的攻击力的怪兽的攻击对象时才能发动。那次攻击无效，这张卡给1只攻击对象怪兽装备。装备怪兽的攻击力上升那个时候的攻击怪兽和攻击对象怪兽的攻击力差的数值。'),
(7025445, 'Power Giant', '强力巨人', 'パワー・ジャイアント', 'Effect Monster', 'Rock', 'EARTH', 6, 2200, NULL, '这张卡可以把手卡1只4星以下的怪兽送去墓地，从手卡特殊召唤。这个方法特殊召唤的场合，这张卡的等级下降从手卡送去墓地的怪兽的等级数值。此外，这张卡进行战斗的场合，直到那次伤害步骤结束时自己受到的效果伤害变成0。'),
(89547299, 'Power Injector', '力量注射师', 'パワー・インジェクター', 'Effect Monster', 'Psychic', 'EARTH', 4, 1300, 1400, '支付600基本分发动。那个回合中场上表侧表示存在的全部念动力族怪兽的攻击力上升500。这个效果1回合只能使用1次。'),
(18842395, 'Power Invader', '强力侵略者', 'パワー・インベーダー', 'Effect Monster', 'Fiend', 'DARK', 5, 2200, NULL, '对方场上有怪兽2只以上存在的场合，这张卡可以不用解放作召唤。'),
(300201001, 'Power of Dark', NULL, NULL, 'Skill Card', 'Yugi', NULL, NULL, NULL, NULL, NULL),
(300302016, 'Power of Friendship', NULL, NULL, 'Skill Card', 'Tea Gardner', NULL, NULL, NULL, NULL, NULL),
(77027445, 'Power of Kaishin', '波塞冬之力', 'ポセイドンの力', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '水族才能装备。1只装备怪兽的攻击力和守备力上升300。'),
(1118137, 'Power of the Guardians', '守护者之力', 'ガーディアンの力', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：装备怪兽进行战斗的攻击宣言时发动。给这张卡放置1个魔力指示物。 ②：装备怪兽的攻击力·守备力上升这张卡的魔力指示物数量×500。 ③：装备怪兽被战斗·效果破坏的场合，可以作为代替把自己场上1个魔力指示物取除。'),
(81650695, 'Power Patron DoomZ', '狱神机 终刻', '獄神機Doom－Z', 'Effect Monster', 'Machine', 'WIND', 1, 300, 200, '这个卡名的②③的效果1回合各能使用1次。 ①：自己不是超量怪兽不能从额外卡组特殊召唤。 ②：以自己场上1只其他的效果怪兽为对象才能发动。把持有和那只自己怪兽的等级相同数值的阶级的1只「终刻」超量怪兽或「坏狱神 朱庇特」在作为对象的怪兽上面重叠当作超量召唤从额外卡组特殊召唤，把自己场上的这张卡当作装备魔法卡使用来装备。 ③：这张卡被破坏的场合才能发动。从卡组把1张「终刻」卡加入手卡。'),
(17473466, 'Power Patron Shadow Beast Nervedo', NULL, NULL, 'Pendulum Effect Monster', 'Illusion', 'DARK', 10, 300, 200, NULL),
(43871165, 'Power Patron Shadow Machine Zegredo', NULL, NULL, 'Pendulum Effect Monster', 'Machine', 'DARK', 10, 300, 200, NULL),
(10266279, 'Power Patron Shadow Spirit Junordo', NULL, NULL, 'Pendulum Effect Monster', 'Fiend', 'DARK', 10, 300, 200, NULL),
(90246973, 'Power Pickaxe', '动力镐', 'パワー・ピカクス', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '1回合1次，可以选择持有装备怪兽的等级以下的等级的对方墓地存在的1只怪兽从游戏中除外，直到结束阶段时装备怪兽的攻击力上升500。'),
(68075840, 'Power Pro Knight Sisters', '球骑士三人娘', '球騎士の三人娘', 'Normal Monster', 'Warrior', 'LIGHT', 4, 1200, 2400, '力量棒球界的向导三人娘。 （左）开朗活泼且责任感强，但爱忘事美中不足的「小帕」。 （右）端庄文雅且认真&冷静，然而有时也会暴走的「小瓦」。 （中）以包包为特征的俩人大前辈「奈美纪」和她的爱犬「竹轮」。 仿佛就像受到了她们的引导，迈入了球场之中，终于抵达命运的所在。随后，球儿们迈出了那一大步。——这是一切的开端，一段伟大的球史。'),
(49858495, 'Power Pro Lady Sisters', '力量棒球女郎三姐妹', 'パワプロ・レディ三姉妹', 'Normal Monster', 'Winged Beast', 'WIND', 6, 1950, 2100, '非常要好的力量棒球三人娘。那份对棒球的热情在球场上华丽飞舞！ 早川苍：系列首位女子选手。是个使用下手投法的投手，决胜球是『海洋球』。橘水月的前辈。 橘水月：既轻佻又好胜的投手。决胜球是『新月球』。喜欢力量堂的「布丁」。 六道圣：拥有罕见棒球才能的接手。和橘水月从初中时代开始就是挚友。最爱吃力量堂的「金锷」。'),
(55063681, 'Power Supplier', '力量供给者', 'パワー・サプライヤー', 'Effect Monster', 'Spellcaster', 'EARTH', 2, 400, 400, '1回合1次，选择自己场上表侧表示存在的1只怪兽才能发动。只要这张卡在自己场上表侧表示存在，选择的怪兽的攻击力上升400。'),
(63265554, 'Power Tool Braver Dragon', '动力工具勇气龙', 'パワー・ツール・ブレイバー・ドラゴン', 'Synchro Monster', 'Machine', 'EARTH', 9, 2500, 2300, '调整＋调整以外的怪兽1只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤成功的场合才能发动。从自己的卡组·墓地选最多3张装备魔法卡给这张卡装备（同名卡最多1张）。 ②：自己·对方的主要阶段，把这张卡装备的自己场上1张装备魔法卡送去墓地，以场上1只效果怪兽为对象才能发动。那只怪兽的表示形式变更或效果直到回合结束时无效。'),
(2403771, 'Power Tool Dragon', '动力工具龙', 'パワー・ツール・ドラゴン', 'Synchro Monster', 'Machine', 'EARTH', 7, 2300, 2500, '调整＋调整以外的怪兽1只以上 ①：1回合1次，自己主要阶段才能发动。从卡组把3张装备魔法卡给对方观看，对方从那之中随机选1张。那1张卡加入自己手卡，剩余回到卡组。 ②：这张卡被破坏的场合，可以作为代替把这张卡装备的1张装备魔法卡送去墓地。'),
(68084557, 'Power Tool Mecha Dragon', '机械龙 动力工具', '機械竜 パワー・ツール', 'Synchro Monster', 'Machine', 'DARK', 7, 2300, 2500, '调整＋调整以外的怪兽1只以上 这个卡名的①的效果1回合只能使用1次。 ①：自己回合，这张卡有装备魔法卡被装备时才能发动。自己从卡组抽1张。 ②：1回合1次，以给其他怪兽装备的1张表侧表示的装备卡为对象才能发动。那张卡给这张卡装备。这个效果在对方回合也能发动。'),
(300302021, 'Power Up!', NULL, NULL, 'Skill Card', 'Yami Yugi', NULL, NULL, NULL, NULL, NULL),
(19434243, 'Power Vice Dragon', NULL, NULL, 'Effect Monster', 'Dragon', 'DARK', 5, 2000, 2400, NULL),
(76403456, 'Power Wall', '力量之壁', 'パワー・ウォール', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：对方怪兽的攻击要让自己受到战斗伤害的伤害计算时才能发动。直到那次战斗发生的对自己的战斗伤害变成0为止，作为受到的伤害的代替而把每500伤害1张卡从自己卡组上面送去墓地。'),
(78586116, 'Power-Up Adapter', '加电插头', 'パワーアップ・コネクター', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '发动后这张卡变成装备卡，给自己场上表侧表示存在的1只名字带有「变形斗士」的怪兽装备。装备怪兽不能攻击。被这个效果装备时，选择装备怪兽以外的场上表侧表示存在的1只怪兽。选择的怪兽的攻击力上升装备怪兽的攻击力数值。'),
(15844566, 'Powercode Talker', '力码语者', 'パワーコード・トーカー', 'Link Monster', 'Cyberse', 'FIRE', NULL, 2300, NULL, '怪兽3只 ①：1回合1次，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的效果直到回合结束时无效。 ②：1回合1次，这张卡和对方怪兽进行战斗的伤害计算时，把这张卡所连接区1只自己怪兽解放才能发动。这张卡的攻击力只在那次伤害计算时变成原本攻击力的2倍。'),
(87742943, 'Powered Crawler', '强化履带车', 'パワードクロウラー', 'Effect Monster', 'Machine', 'EARTH', 7, 2700, 2000, '这个卡名的①的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。选持有比这张卡低的攻击力的对方场上1只怪兽破坏。 ②：只要这张卡在怪兽区域存在，可以攻击的对方怪兽必须作出攻击。'),
(46132282, 'Powered Inzektron', '甲化铠骨骼', '甲化鎧骨格', 'Synchro Monster', 'Machine', 'LIGHT', 6, 2500, 1600, '调整＋调整以外的怪兽1只以上 ①：这张卡同调召唤成功的场合发动。这个回合，这张卡不会被战斗·效果破坏，自己受到的全部伤害变成0。'),
(50621530, 'Powered Tuner', '强化调整龙', 'パワード・チューナー', 'Effect Monster', 'Dragon', 'WATER', 4, 1400, 1000, '这张卡的攻击力上升场上表侧表示存在的调整数量×500的数值。'),
(300302037, 'Powerful Group of Guys', NULL, NULL, 'Skill Card', 'Aster Phoenix', NULL, NULL, NULL, NULL, NULL),
(84298614, 'Powerful Rebirth', '强化苏生', '強化蘇生', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：以自己墓地1只4星以下的怪兽为对象才能把这张卡发动。那只怪兽特殊召唤。只要这张卡在魔法与陷阱区域存在，那只怪兽的等级上升1星，攻击力·守备力上升100。那只怪兽破坏时这张卡破坏。'),
(35100834, 'Powerhold the Moving Battery', '机动炮垒 强力堡垒', '機動砲塁 パワー・ホールド', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：这张卡发动后变成效果怪兽（机械族·地·4星·攻0/守2000）在怪兽区域特殊召唤。那之后，可以从手卡·卡组选1只机械族·4星的「零件」怪兽当作装备卡使用给这张卡装备。这张卡也当作陷阱卡使用。 ②：这张卡的效果特殊召唤的这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力2倍的数值。'),
(67234805, 'Powersink Stone', '能力吸收石', '能力吸収石', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '①：只要这张卡在魔法与陷阱区域存在，每次怪兽的效果发动，给这张卡放置1个魔石指示物（最多2个）。 ②：只要这张卡有2个魔石指示物放置中，场上的表侧表示怪兽的效果无效化，双方不能把场上的表侧表示怪兽的效果发动。 ③：自己·对方的结束阶段，这张卡有魔石指示物放置中的场合发动。这张卡的魔石指示物全部取除。'),
(33691040, 'Pragtical', '尖刺龙', 'プラグティカル', 'Fusion Monster', 'Dinosaur', 'EARTH', 5, 1900, 1500, '「虎纹龙」＋「火焰毒蛇」'),
(81997228, 'Prank-Kids Battle Butler', '调皮宝贝屋子管家', 'プランキッズ・ハウスバトラー', 'Fusion Monster', 'Thunder', 'WIND', 10, 3000, 3000, '「调皮宝贝·火灯娃」＋「调皮宝贝·水滴娃」＋「调皮宝贝·脉冲娃」 这张卡不用融合召唤不能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：把这张卡解放才能发动。对方场上的怪兽全部破坏。这个效果在对方回合也能发动。 ②：这张卡被对方送去墓地的场合，以融合怪兽以外的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(43886072, 'Prank-Kids Bow-Wow-Bark', '调皮宝贝汪汪狗', 'プランキッズ・バウワウ', 'Link Monster', 'Pyro', 'FIRE', NULL, 2000, NULL, '「调皮宝贝」怪兽2只 这个卡名的②的效果1回合只能使用1次。 ①：这张卡所连接区的「调皮宝贝」怪兽的攻击力上升1000。 ②：对方回合把这张卡解放，以连接怪兽以外的自己墓地2张「调皮宝贝」卡为对象才能发动（同名卡最多1张）。那些卡加入手卡。此外，这个回合自己场上的「调皮宝贝」怪兽不会被对方的效果破坏。'),
(17382973, 'Prank-Kids Dodo-Doodle-Doo', '调皮宝贝喔喔鸡', 'プランキッズ・ドゥードゥル', 'Link Monster', 'Thunder', 'WIND', NULL, 2000, NULL, '「调皮宝贝」怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡连接召唤成功的场合才能发动。从卡组把1张「调皮宝贝」魔法·陷阱卡加入手卡。 ②：把这张卡解放，以连接怪兽以外的自己墓地2张「调皮宝贝」卡为对象才能发动（同名卡最多1张）。那些卡加入手卡。'),
(55725117, 'Prank-Kids Dropsies', '调皮宝贝·水滴娃', 'プランキッズ・ドロップ', 'Effect Monster', 'Aqua', 'WATER', 2, 1000, 1000, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为「调皮宝贝」怪兽的所用融合素材或者所用连接素材送去墓地的场合才能发动。自己回复1000基本分。那之后，可以从手卡·卡组把「调皮宝贝·水滴娃」以外的1只「调皮宝贝」怪兽守备表示特殊召唤。'),
(81119816, 'Prank-Kids Fansies', '调皮宝贝·脉冲娃', 'プランキッズ・パルス', 'Effect Monster', 'Thunder', 'WIND', 1, NULL, 2000, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为「调皮宝贝」怪兽的所用融合素材或者所用连接素材送去墓地的场合才能发动。从卡组把「调皮宝贝·脉冲娃」以外的1张「调皮宝贝」卡送去墓地。那之后，可以从手卡·卡组把「调皮宝贝·脉冲娃」以外的1只「调皮宝贝」怪兽守备表示特殊召唤。'),
(18236002, 'Prank-Kids Lampsies', '调皮宝贝·火灯娃', 'プランキッズ・ランプ', 'Effect Monster', 'Pyro', 'FIRE', 3, 1500, 500, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为「调皮宝贝」怪兽的所用融合素材或者所用连接素材送去墓地的场合才能发动。给与对方500伤害。那之后，可以从手卡·卡组把「调皮宝贝·火灯娃」以外的1只「调皮宝贝」怪兽守备表示特殊召唤。'),
(25725326, 'Prank-Kids Meow-Meow-Mu', '调皮宝贝喵喵猫', 'プランキッズ・ミュー', 'Link Monster', 'Rock', 'EARTH', NULL, 1000, NULL, '4星以下的「调皮宝贝」怪兽1只 自己对「调皮宝贝喵喵猫」1回合只能有1次连接召唤，那个效果1回合只能使用1次。 ①：对方回合自己场上的「调皮宝贝」怪兽为让效果发动而把自身解放的场合，可以作为代替把场上·墓地的这张卡除外。'),
(79059098, 'Prank-Kids Pandemonium', '调皮宝贝的大暴走', 'プランキッズの大暴走', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：自己·对方的主要阶段才能发动。从自己的手卡·场上把「调皮宝贝」融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。这张卡的发动后，直到回合结束时自己不是「调皮宝贝」怪兽不能召唤·特殊召唤。'),
(16269385, 'Prank-Kids Place', '调皮宝贝屋', 'プランキッズ・ハウス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「调皮宝贝」怪兽加入手卡。 ②：1回合1次，自己对「调皮宝贝」融合怪兽的融合召唤成功的场合才能发动。自己场上的全部怪兽的攻击力上升500。 ③：1回合1次，自己对「调皮宝贝」连接怪兽的连接召唤成功的场合才能发动。对方场上的全部怪兽的攻击力下降500。'),
(15447747, 'Prank-Kids Plan', '调皮宝贝的大作战', 'プランキッズの大作戦', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方的主要阶段才能发动。用自己场上的「调皮宝贝」怪兽为素材把1只「调皮宝贝」连接怪兽连接召唤。 ②：对方怪兽的攻击宣言时把墓地的这张卡除外才能发动。选自己墓地的「调皮宝贝」卡任意数量回到卡组，那只攻击怪兽的攻击力直到回合结束时下降回去数量×100。'),
(43664494, 'Prank-Kids Pranks', '调皮宝贝捣蛋记', 'プランキッズ・プランク', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从手卡丢弃1张「调皮宝贝」卡才能发动。在自己场上把1只「调皮宝贝衍生物」（炎族·炎·1星·攻/守0）特殊召唤。这衍生物不能解放。 ②：自己结束阶段以「调皮宝贝捣蛋记」以外的自己墓地3张「调皮宝贝」卡为对象才能发动。那3张卡加入卡组洗切。那之后，自己从卡组抽1张。'),
(70875686, 'Prank-Kids Rip-Roarin-Roaster', '调皮宝贝吼吼龙', 'プランキッズ・ロアゴン', 'Link Monster', 'Aqua', 'WATER', NULL, 3000, NULL, '「调皮宝贝」怪兽2只以上 这张卡不用连接召唤不能特殊召唤。这个卡名的②的效果1回合只能使用1次。 ①：把这张卡解放才能发动。对方场上的魔法·陷阱卡全部破坏。这个效果在对方回合也能发动。 ②：这张卡被对方送去墓地的场合，以连接怪兽以外的自己墓地1张卡为对象才能发动。那张卡加入手卡。'),
(18514525, 'Prank-Kids Rocket Ride', '调皮宝贝火箭', 'プランキッズ・ロケット', 'Fusion Monster', 'Pyro', 'FIRE', 5, 2000, NULL, '「调皮宝贝」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤成功的场合才能发动。这个回合这张卡攻击力下降1000，并且也能直接攻击。 ②：把这张卡解放，以融合怪兽以外的自己墓地2只「调皮宝贝」怪兽为对象才能发动（同名卡最多1张）。那些怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不能攻击。'),
(31440046, 'Prank-Kids Rocksies', '调皮宝贝·岩石娃', 'プランキッズ・ロック', 'Effect Monster', 'Rock', 'EARTH', 4, 1500, 1500, '这个卡名的效果1回合只能使用1次。 ①：这张卡作为「调皮宝贝」怪兽的所用融合素材或者所用连接素材送去墓地的场合才能发动。自己1张手卡除外，自己从卡组抽1张。那之后，可以从手卡·卡组把「调皮宝贝·岩石娃」以外的1只「调皮宝贝」怪兽守备表示特殊召唤。'),
(44509529, 'Prank-Kids Weather Washer', '调皮宝贝气象机', 'プランキッズ・ウェザー', 'Fusion Monster', 'Aqua', 'WATER', 5, 2000, NULL, '「调皮宝贝」怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：自己的「调皮宝贝」怪兽攻击的场合，对方直到伤害步骤结束时魔法·陷阱·怪兽的效果不能发动。 ②：对方回合把这张卡解放，以融合怪兽以外的自己墓地2只「调皮宝贝」怪兽为对象才能发动（同名卡最多1张）。那些怪兽特殊召唤。这个效果特殊召唤的怪兽在这个回合不会被战斗破坏。'),
(52472775, 'Prayers of the Voiceless Voice', '肃声祈祷', '粛声なる祈り', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '这个卡名的②的效果1回合只能使用1次。 ①：等级合计直到变成仪式召唤的怪兽的等级以上为止，把自己的手卡·场上的光属性怪兽解放，从手卡把1只光属性仪式怪兽仪式召唤。 ②：自己场上的表侧表示的光属性仪式怪兽因对方的效果从场上离开的场合，把墓地的这张卡除外才能发动。从手卡·卡组把「古圣戴 始龙」「龙姬神 萨菲拉」「肃声之守护者 法理守护者」的其中1只无视召唤条件特殊召唤。'),
(31600513, 'Praying Mantis', '祈祷螳螂', 'プレイング・マンティス', 'Effect Monster', 'Insect', 'WIND', 4, 1500, 1200, '这个卡名的①③的效果1回合各能使用1次。 ①：自己准备阶段才能发动。在自己场上把1只「小螳螂衍生物」（昆虫族·风·1星·攻/守500）特殊召唤。 ②：1回合1次，对方怪兽的攻击宣言时，把自己的魔法与陷阱区域1张卡送去墓地才能发动。那只对方怪兽回到持有者手卡。 ③：把墓地的这张卡除外才能发动。在自己场上把1只「小螳螂衍生物」特殊召唤。'),
(13048472, 'Pre-Preparation of Rites', '仪式的事前准备', '儀式の下準備', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从卡组选1张仪式魔法卡，再从自己的卡组·墓地选1只在那张仪式魔法卡有卡名记述的仪式怪兽。那2张卡加入手卡。'),
(68304813, 'Precious Cards from Beyond', '冥界的宝牌', '冥界の宝札', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '①：自己作把怪兽2只以上解放的上级召唤成功的场合发动。自己从卡组抽2张。'),
(51858200, 'Predaplanet', '捕食行星', '捕食惑星', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '「捕食惑星」的①的效果1回合只能使用1次。 ①：这张卡在魔法与陷阱区域存在，有捕食指示物放置的怪兽从场上离开的场合发动。从卡组把1张「捕食」卡加入手卡。 ②：把墓地的这张卡除外才能发动。从自己的手卡·场上把融合怪兽卡决定的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。这个效果融合召唤的场合，不是「捕食植物」怪兽不能作为融合素材。'),
(44536921, 'Predaplanning', '捕食计划', '捕食計画', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：从卡组把1只「捕食植物」怪兽送去墓地才能发动。给场上的全部表侧表示怪兽各放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。 ②：这张卡在墓地存在的状态，自己把暗属性怪兽融合召唤的场合，把这张卡除外，以场上1张卡为对象才能发动。那张卡破坏。'),
(66309175, 'Predaplant Ambulomelides', '捕食植物 蓬谷陆行鲸', '捕食植物アンブロメリドゥス', 'Fusion Monster', 'Plant', 'DARK', 5, 1000, 2500, '「捕食植物」怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡融合召唤的场合才能发动。从自己的卡组·额外卡组（表侧）·墓地把1只「捕食植物」怪兽或1张「捕食」魔法·陷阱卡加入手卡。 ②：以1只对方场上的有捕食指示物放置的怪兽或者自己场上的怪兽为对象才能发动。那只怪兽解放，从卡组把1只「捕食植物」怪兽特殊召唤。'),
(66787942, 'Predaplant Baalthea', NULL, NULL, 'Synchro Tuner Monster', 'Plant', 'DARK', 4, 1900, 1000, NULL),
(22138839, 'Predaplant Banksiogre', '捕食植物 佛塔树食人魔', '捕食植物バンクシアオーガ', 'Tuner Monster', 'Plant', 'DARK', 6, 2000, 100, '①：这张卡把对方场上1只有捕食指示物放置的怪兽解放的场合可以从手卡特殊召唤。 ②：这张卡从场上送去墓地的场合发动。给对方场上的表侧表示怪兽全部各放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。'),
(70427670, 'Predaplant Bufolicula', '捕食植物 土瓶草蟾蜍', '捕食植物ブフォリキュラ', 'Pendulum Effect Monster', 'Plant', 'DARK', 1, NULL, NULL, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡成为融合召唤的素材，被送去墓地的场合或者表侧加入额外卡组的场合才能发动。从自己的额外卡组（表侧）把「捕食植物 土瓶草蟾蜍」以外的1只暗属性灵摆怪兽加入手卡。'),
(44932065, 'Predaplant Byblisp', '捕食植物 腺毛草胡蜂', '捕食植物ビブリスプ', 'Effect Monster', 'Plant', 'DARK', 1, NULL, 1900, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被送去墓地的场合才能发动。从卡组把「捕食植物 腺毛草胡蜂」以外的1只「捕食植物」怪兽加入手卡。 ②：这张卡在墓地存在，场上的怪兽有捕食指示物放置中的场合才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(25586143, 'Predaplant Chimerafflesia', '捕食植物 奇美拉大王花', '捕食植物キメラフレシア', 'Fusion Monster', 'Plant', 'DARK', 7, 2500, 2000, '「捕食植物」怪兽＋暗属性怪兽 ①：1回合1次，以持有这张卡的等级以下的等级的场上1只怪兽为对象才能发动。那只怪兽除外。 ②：这张卡和对方的表侧表示怪兽进行战斗的攻击宣言时才能发动。直到回合结束时，那只对方怪兽的攻击力下降1000，这张卡的攻击力上升1000。 ③：这张卡被送去墓地的场合，下次的准备阶段才能发动。从卡组把1张「融合」魔法卡加入手卡。'),
(89181134, 'Predaplant Chlamydosundew', '捕食植物 毛毡伞蜥蜴', '捕食植物サンデウ・キンジー', 'Effect Monster', 'Plant', 'DARK', 2, 600, 200, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己要作为融合素材的有捕食指示物放置的怪兽的属性当作暗属性使用。 ②：自己主要阶段才能发动。暗属性融合怪兽卡决定的包含场上的这张卡的融合素材怪兽从自己的手卡·场上以及对方场上的有捕食指示物放置的怪兽之中选出送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(7161742, 'Predaplant Cordyceps', '捕食植物 冬虫夏草', '捕食植物コーディセップス', 'Effect Monster', 'Plant', 'DARK', 1, NULL, NULL, '①：自己准备阶段把墓地的这张卡除外，以自己墓地2只4星以下的「捕食植物」怪兽为对象才能发动。那些怪兽特殊召唤。这个效果的发动后，直到回合结束时自己不能通常召唤，不是融合怪兽不能特殊召唤。'),
(61677004, 'Predaplant Darlingtonia Cobra', '捕食植物 百合眼镜蛇', '捕食植物ダーリング・コブラ', 'Effect Monster', 'Plant', 'DARK', 3, 1000, 1500, '这个卡名的效果在决斗中只能使用1次。 ①：这张卡用「捕食植物」怪兽的效果特殊召唤的场合才能发动。从卡组把1张「融合」魔法卡加入手卡。'),
(69946549, 'Predaplant Dragostapelia', '捕食植物 魔星花龙', '捕食植物ドラゴスタペリア', 'Fusion Monster', 'Plant', 'DARK', 8, 2700, 1900, '融合怪兽＋暗属性怪兽 ①：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。给那只怪兽放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。这个效果在对方回合也能发动。 ②：只要这张卡在怪兽区域存在，对方发动的有捕食指示物放置的怪兽的效果无效化。'),
(99913726, 'Predaplant Drosophyllum Hydra', '捕食植物 露松九头蛇', '捕食植物ドロソフィルム・ヒドラ', 'Effect Monster', 'Plant', 'DARK', 5, 800, 2300, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：这张卡把自己或者对方场上1只有捕食指示物放置的怪兽解放的场合可以从手卡·墓地特殊召唤。 ②：这张卡在场上·墓地存在的场合，把这张卡以外的自己墓地1只「捕食植物」怪兽除外，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力下降500。这个效果在对方回合也能发动。'),
(96622984, 'Predaplant Flytrap', '捕食植物 苍蝇地狱草', '捕食植物フライ・ヘル', 'Effect Monster', 'Plant', 'DARK', 2, 400, 800, '①：1回合1次，以对方场上1只表侧表示怪兽为对象才能发动。给那只怪兽放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。 ②：这张卡和持有这张卡的等级以下的等级的怪兽进行战斗的伤害步骤开始时才能发动。那只怪兽破坏。那之后，这张卡的等级上升破坏的那只怪兽的原本等级数值。'),
(5259518, 'Predaplant Heliamphorhynchus', '捕食植物 太阳瓶草喙嘴龙', '捕食植物ヘリアンフォリンクス', 'Effect Monster', 'Plant', 'DARK', 8, 1200, 2400, '这个卡名的①②的效果1回合各能使用1次。 ①：对方场上的怪兽有捕食指示物放置中的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡被对方破坏的场合，以「捕食植物 卷瓶子草喙嘴龙」以外的自己墓地1只龙族·植物族的暗属性怪兽为对象才能发动。那只怪兽特殊召唤。'),
(18595008, 'Predaplant Lilizard', NULL, NULL, 'Effect Monster', 'Plant', 'DARK', 3, 1200, 1200, NULL),
(44994712, 'Predaplant Longinephila', NULL, NULL, 'Tuner Monster', 'Plant', 'DARK', 1, 600, 100, NULL),
(22011689, 'Predaplant Moray Nepenthes', '捕食植物 海鳝猪笼草', '捕食植物モーレイ・ネペンテス', 'Effect Monster', 'Plant', 'DARK', 4, 1600, 1000, '①：这张卡的攻击力上升场上的捕食指示物数量×200。 ②：这张卡战斗破坏对方怪兽时才能发动。那只破坏的怪兽当作装备卡使用给这张卡装备。 ③：1回合1次，以这张卡的效果装备的1张怪兽卡为对象才能发动。那张卡破坏，自己基本分回复那个原本攻击力的数值。'),
(35272499, 'Predaplant Ophrys Scorpio', '捕食植物 蜂兰蝎', '捕食植物オフリス・スコーピオ', 'Effect Monster', 'Plant', 'DARK', 3, 1200, 800, '这个卡名的效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤的场合，从手卡把1只怪兽送去墓地才能发动。从卡组把「捕食植物 蜂兰蝎」以外的1只「捕食植物」怪兽特殊召唤。'),
(26308721, 'Predaplant Pterapenthes', '捕食植物 猪笼草翼龙', '捕食植物プテロペンテス', 'Effect Monster', 'Plant', 'DARK', 3, 300, 2100, '①：这张卡给与对方战斗伤害时，以对方场上1只表侧表示怪兽为对象才能发动。给那只怪兽放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。 ②：1回合1次，以持有这张卡的等级以下的等级的对方场上1只怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。'),
(53819028, 'Predaplant Sarraceniant', '捕食植物 瓶子草蚁', '捕食植物セラセニアント', 'Effect Monster', 'Plant', 'DARK', 1, 100, 600, '「捕食植物 瓶子草蚁」的③的效果1回合只能使用1次。 ①：对方怪兽的直接攻击宣言时才能发动。这张卡从手卡特殊召唤。 ②：这张卡和对方怪兽进行战斗的伤害计算后才能发动。那只对方怪兽破坏。 ③：场上的这张卡被效果送去墓地的场合或者被战斗破坏的场合才能发动。从卡组把「捕食植物 瓶子草蚁」以外的1张「捕食」卡加入手卡。'),
(30537973, 'Predaplant Spider Orchid', '捕食植物 蜘蛛兰', '捕食植物スパイダー・オーキッド', 'Pendulum Effect Monster', 'Plant', 'DARK', 1, NULL, NULL, '这个卡名的怪兽效果1回合只能使用1次。 ①：这张卡召唤·特殊召唤成功的回合的结束阶段，从手卡丢弃1只植物族怪兽才能发动。从卡组把1只4星以下的植物族怪兽加入手卡。'),
(52792430, 'Predaplant Spinodionaea', '捕食植物 棘龙捕蝇草', '捕食植物スピノ・ディオネア', 'Effect Monster', 'Plant', 'DARK', 4, 1800, NULL, '①：这张卡召唤·特殊召唤成功的场合，以对方场上1只表侧表示怪兽为对象才能发动。给那只怪兽放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。 ②：这张卡和持有这张卡的等级以下的等级的怪兽进行战斗的伤害计算后才能发动。从卡组把「捕食植物 捕蝇草棘龙」以外的1只「捕食植物」怪兽特殊召唤。'),
(69105797, 'Predaplant Squid Drosera', '捕食植物 鱿鱼茅膏菜', '捕食植物スキッド・ドロセーラ', 'Effect Monster', 'Plant', 'DARK', 2, 800, 400, '①：把这张卡从手卡送去墓地，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽可以向有捕食指示物放置的对方怪兽全部各作1次攻击。 ②：表侧表示的这张卡从场上离开的场合发动。给对方场上的特殊召唤的怪兽全部各放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。'),
(17825378, 'Predaplant Triantis', '捕食植物 黏菖蒲螳螂', '捕食植物トリアンティス', 'Pendulum Effect Monster', 'Plant', 'DARK', 8, 2400, 1000, '①：这张卡成为融合召唤的素材，被送去墓地的场合或者表侧加入额外卡组的场合才能发动。选最多有自己场上的怪兽数量的场上的表侧表示怪兽。给那些怪兽各放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。'),
(79864860, 'Predaplant Triphyoverutum', '捕食植物 三首剧毒穗叶藤龙', '捕食植物トリフィオヴェルトゥム', 'Fusion Monster', 'Plant', 'DARK', 9, 3000, 3000, '场上的暗属性怪兽×3 这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的攻击力上升这张卡以外的有捕食指示物放置的怪兽的原本攻击力的合计数值。 ②：这张卡是已融合召唤的场合，对方从额外卡组把怪兽特殊召唤之际才能发动。那次特殊召唤无效，那些怪兽破坏。 ③：对方场上的怪兽有捕食指示物放置中的场合才能发动。这张卡从墓地守备表示特殊召唤。'),
(70369116, 'Predaplant Verte Anaconda', '捕食植物 食虫粉衣凤梨森蚺', '捕食植物ヴェルテ・アナコンダ', 'Link Monster', 'Plant', 'DARK', NULL, 500, NULL, '效果怪兽2只 这个卡名的①②的效果1回合各能使用1次。 ①：以场上1只表侧表示怪兽为对象才能发动。那只怪兽直到回合结束时变成暗属性。 ②：支付2000基本分，把1张「融合」通常·速攻魔法卡从卡组送去墓地才能发动。这个效果变成和那张魔法卡发动时的效果相同。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤。'),
(72129804, 'Predaplast', '捕食生成', '捕食生成', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '①：把手卡的「捕食」卡任意数量给对方观看，以给人观看的数量的对方场上的表侧表示怪兽为对象才能发动。给那些怪兽各放置1个捕食指示物。有捕食指示物放置的2星以上的怪兽的等级变成1星。 ②：自己的「捕食植物」怪兽被战斗破坏的场合，可以作为代替把墓地的这张卡除外。'),
(88069597, 'Predaponics', '捕食花盆', 'プレデター・プランター', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这张卡的控制者在每次自己准备阶段支付800基本分。或者不支付基本分让这张卡破坏。 ①：1回合1次，自己主要阶段才能发动。从自己的手卡·墓地选1只4星以下的「捕食植物」怪兽特殊召唤。这个效果特殊召唤的怪兽的效果无效化。'),
(31643613, 'Predapractice', '捕食活动', '捕食活動', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：从手卡把1只「捕食植物」怪兽特殊召唤。那之后，从卡组把「捕食活动」以外的1张「捕食」卡加入手卡。这张卡的发动后，直到回合结束时自己不是融合怪兽不能从额外卡组特殊召唤。'),
(8148322, 'Predaprime Fusion', '捕食优选结合', 'プレデター・プライム・フュージョン', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：场上有「捕食植物」怪兽存在的场合才能发动。从自己·对方场上把暗属性融合怪兽卡决定的包含自己场上的暗属性怪兽2只以上在内的融合素材怪兽送去墓地，把那1只融合怪兽从额外卡组融合召唤。'),
(89176044, 'Predaprimitive', NULL, NULL, 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(14463695, 'Predapruning', '捕食嫁接木', '捕食接ぎ木', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：以自己墓地1只「捕食植物」怪兽为对象才能把这张卡发动。那只怪兽特殊召唤，把这张卡装备。这张卡从场上离开时那只怪兽破坏。'),
(31118030, 'Prediction Princess Arrowsylph', '占术姬 弓箭风精', '占術姫アローシルフ', 'Flip Effect Monster', 'Fairy', 'WIND', 4, 1000, 1400, '①：这张卡反转的场合才能发动。从自己的卡组·墓地选1张仪式魔法卡加入手卡。'),
(5010422, 'Prediction Princess Astromorrigan', '占术姬 通灵板摩莉甘', '占術姫ウィジャモリガン', 'Flip Effect Monster', 'Fairy', 'DARK', 3, 1300, NULL, '①：这张卡反转的场合发动。那个回合的结束阶段把对方场上的守备表示怪兽全部破坏，给与对方破坏的怪兽数量×500伤害。'),
(66069967, 'Prediction Princess Bibliomuse', '占术姬 书本缪斯', '占術姫ビブリオムーサ', 'Flip Effect Monster', 'Fairy', 'EARTH', 9, 2500, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡被解放送去墓地的场合才能发动。这张卡里侧守备表示特殊召唤。 ②：这张卡反转的场合才能发动。从卡组把「占术姬 书本缪斯」以外的1只「占术姬」怪兽和1张仪式魔法卡加入手卡。 ③：只要这张卡在怪兽区域存在，自己场上的仪式怪兽不会成为对方的效果的对象，不会被对方的效果破坏。'),
(32231618, 'Prediction Princess Coinorma', '占术姬 硬币地精', '占術姫コインノーマ', 'Flip Effect Monster', 'Fairy', 'EARTH', 3, 800, 1400, '①：这张卡反转的场合才能发动。从手卡·卡组把1只3星以上的反转怪兽里侧守备表示特殊召唤。这个效果的发动后，直到回合结束时自己不能把「占术姬」怪兽以外的怪兽的效果发动。'),
(67503139, 'Prediction Princess Crystaldine', '占术姬 水晶球水精', '占術姫クリスタルウンディーネ', 'Flip Effect Monster', 'Fairy', 'WATER', 5, 1400, 2200, '①：这张卡反转的场合才能发动。从自己的卡组·墓地选1只仪式怪兽加入手卡。'),
(68625727, 'Prediction Princess Petalelf', '占术姬 花瓣精灵', '占術姫ペタルエルフ', 'Flip Effect Monster', 'Fairy', 'EARTH', 3, 800, 700, '①：这张卡反转的场合才能发动。对方场上的表侧攻击表示怪兽全部变成守备表示。这个效果变成守备表示的怪兽不能把表示形式变更。'),
(94997874, 'Prediction Princess Tarotrei', '圣占术姬 塔罗光巫女', '聖占術姫タロットレイ', 'Ritual Effect Monster', 'Fairy', 'LIGHT', 9, 2700, 1200, '「圣占术的仪式」降临。这个卡名的①②的效果1回合只能有1次使用其中任意1个，对方回合也能发动。 ①：以场上1只里侧表示怪兽为对象才能发动。那只怪兽变成表侧攻击表示。 ②：以场上1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。 ③：自己结束阶段才能发动。从自己的手卡·墓地选1只反转怪兽里侧守备表示特殊召唤。'),
(42932862, 'Prediction Princess Tarotreith', '冥占术姬 塔罗幽巫女', '冥占術姫タロットレイス', 'Ritual Effect Monster', 'Fairy', 'DARK', 9, 1200, 2700, '「冥占术的仪式」降临。这张卡用仪式召唤以及「圣占术姬 塔罗光巫女」的效果才能特殊召唤。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡反转的场合才能发动。从卡组把1只反转怪兽里侧守备表示特殊召唤。 ②：自己·对方回合，可以从以下效果选择1个发动。 ●选自己场上的里侧表示怪兽任意数量变成表侧守备表示。 ●选自己场上的表侧表示怪兽任意数量变成里侧守备表示。'),
(30392583, 'Prediction Ritual', '圣占术的仪式', '聖占術の儀式', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「圣占术姬 塔罗光巫女」的降临必需。 ①：从自己的手卡·场上把等级合计直到9以上的怪兽解放，从手卡把「圣占术姬 塔罗光巫女」仪式召唤。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把1只「占术姬」怪兽加入手卡。这个效果在这张卡送去墓地的回合不能发动。'),
(70828912, 'Premature Burial', '过早的埋葬', '早すぎた埋葬', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '①：支付800基本分，以自己墓地1只怪兽为对象才能把这张卡发动。那只怪兽攻击表示特殊召唤，把这张卡装备。这张卡破坏时那只怪兽破坏。'),
(95083785, 'Premature Return', '过早的归还', '早すぎた帰還', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '①：把1张手卡除外，以除外的1只自己怪兽为对象才能发动。那只怪兽里侧守备表示特殊召唤。'),
(96729612, 'Preparation of Rites', '仪式的准备', '儀式の準備', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：从卡组把1只7星以下的仪式怪兽加入手卡。那之后，可以从自己墓地把1张仪式魔法卡加入手卡。'),
(4483989, 'Prepare to Strike Back', '反击准备', '反撃準備', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '每次对方玩家对表侧守备表示怪兽进行攻击宣言时，投掷硬币猜正反。 ●猜中的场合：被攻击的表侧守备表示怪兽变成攻击表示。 ●猜错的场合：这张卡的控制者受到攻击怪兽的攻击力超过攻击对象的怪兽的守备力的数值的伤害。'),
(300201004, 'Prescience', NULL, NULL, 'Skill Card', 'Ishizu', NULL, NULL, NULL, NULL, NULL),
(56119752, 'Present Card', '礼物卡', 'プレゼントカード', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '「礼物卡」在1回合只能发动1张。 ①：对方把手卡全部丢弃。那之后，对方从卡组抽5张。'),
(71832012, 'Pressured Planet Wraitsoth', '六世坏・帕拉索眦', '六世壊＝パライゾス', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「俱舍怒威族」怪兽加入手卡。 ②：自己场上的怪兽的攻击力·守备力上升场上的怪兽的属性种类×100。 ③：自己场上的「俱舍怒威族的香格里拉茧」把效果发动的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(549481, 'Prevent Rat', '硬毛鼠', 'プリヴェント・ラット', 'Normal Monster', 'Beast', 'EARTH', 4, 500, 2000, '毛像硬皮一样聚集在一起，守备力非常的高。'),
(94303232, 'Prevention Star', '阻碍星', 'プリベント・スター', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '自己场上表侧攻击表示存在的怪兽的表示形式改变为表侧守备表示的回合，那只怪兽才能装备。选择对方场上存在的1只怪兽。那只怪兽不能作攻击和表示形式的改变。装备怪兽被破坏让这张卡送去墓地时，选择的对方怪兽从游戏中除外。'),
(33055499, 'Prey of the Jirai Gumo', '地雷蜘蛛的饵食', '地雷蜘蛛の餌食', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡发动后变成通常怪兽（昆虫族·地·5星·攻2100/守100）在正对面的自己的主要怪兽区域特殊召唤（也当作陷阱卡使用）。那之后，可以把和这张卡相同纵列1只对方怪兽破坏。 ②：把墓地的这张卡除外才能发动。自己的卡组·除外状态的「雷魔神-桑迦」「风魔神-修迦」「水魔神-斯迦」的其中1只加入手卡。'),
(91559748, 'Prickle Fairy', '棘之妖精', '棘の妖精', 'Effect Monster', 'Plant', 'EARTH', 4, 300, 2000, '对方不破坏这张卡，就不能对昆虫族怪兽进行攻击。与这张卡进行战斗的怪兽，在伤害步骤终了时变成守备表示。'),
(17016131, 'Pride of the Plunder Patroll', '海造贼-夸示', '海造賊－誇示', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合各能使用1次。 ①：自己的「海造贼」怪兽战斗破坏对方怪兽的场合发动。自己从卡组抽1张。 ②：自己场上有「海造贼」怪兽存在的场合，可以把魔法与陷阱区域的表侧表示的这张卡送去墓地，从以下效果选择1个发动。 ●对方从卡组抽1张。那之后，自己把对方手卡确认，选那之内的1只怪兽送去墓地。 ●把对方的额外卡组确认，选那之内的1张送去墓地。'),
(86016245, 'Pride of the Weak', '弱者的意志', '弱者の意地', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '自己手卡是0张的场合，自己场上存在的2星以下的怪兽战斗破坏对方怪兽送去墓地时，从自己卡组抽2张卡。'),
(66518841, 'Prideful Roar', '自尊的咆哮', 'プライドの咆哮', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '战斗伤害计算时，自己怪兽的攻击力比对方怪兽低的场合，支付那个攻击力差的数值的基本分发动。只在伤害计算时，自己怪兽的攻击力上升和对方怪兽的攻击力差的数值＋300。'),
(67660909, 'Priestess of the Ashened City', '灰灭之都的巫女', '灰滅せし都の巫女', 'Effect Monster', 'Pyro', 'DARK', 4, 1200, 1300, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：场地区域有「灰灭之都 奥布西地暮」存在的场合，这张卡可以从手卡特殊召唤。 ②：这张卡召唤·特殊召唤的场合才能发动。从卡组把「灰灭都的巫女」以外的1张「灰灭」卡加入手卡。'),
(36734924, 'Priestess with Eyes of Blue', '青之眼巫女', '青き眼の巫女', 'Tuner Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '「青色眼睛的巫女」的①②的效果1回合只能有1次使用其中任意1个。 ①：场上的表侧表示的这张卡成为效果的对象时才能发动。选自己场上1只效果怪兽送去墓地，从卡组把最多2只「青眼」怪兽加入手卡（同名卡最多1张）。 ②：这张卡在墓地存在的场合，以自己场上1只「青眼」怪兽为对象才能发动。那只怪兽回到持有者卡组，这张卡从墓地特殊召唤。'),
(2507443, 'Prima Light', '首席之光', 'プリマの光', 'Spell Card', 'Quick-Play', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：可以从以下效果选择1个发动。 ●自己场上1只战士族·地属性怪兽解放，从手卡·卡组把1只战士族·光属性怪兽特殊召唤。 ●自己·对方的主要阶段才能发动。进行手卡1只战士族怪兽的召唤。 ②：自己主要阶段把墓地的这张卡除外才能发动。从卡组把1只战士族·天使族的「电子」怪兽加入手卡。'),
(57448410, 'Prima Materiactor', '第一原物质', 'プリマ・マテリアクトル', 'Pendulum Normal Monster', 'Dragon', 'LIGHT', 3, NULL, NULL, '从遥远彼端的天上界突然飞来的外来生命体。虽有众多研究者力图查明真身，但其发放的光辉和弥漫的瘴气导致长久以来其存在被谜团所笼罩，想要一睹全貌极为困难。然而，近年来，经过新进研究者的一番努力发现了许多新种。揭开其全貌的日子想必也已临近。'),
(47435107, 'Primal Cry', '原初的叫唤', '原初の叫喚', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「辉神鸟 贝努鸟」的降临必需。 ①：从自己的手卡·场上把等级合计直到8以上的怪兽解放，从手卡把「辉神鸟 贝努鸟」仪式召唤。 ②：自己结束阶段把墓地的这张卡除外，以这个回合从场上送去墓地的自己墓地1只仪式怪兽为对象才能发动。那只怪兽特殊召唤。'),
(64025981, 'Primal Dragon, the Primordial', '始原龙', '始原竜プライマル・ドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 4, 2000, 2000, '这个卡名的②③的效果1回合各能使用1次。 ①：这张卡的战斗发生的对对方的战斗伤害变成0。 ②：从自己墓地把1只龙族怪兽除外才能发动。这张卡的攻击力·守备力直到下个回合的结束时上升除外的怪兽的攻击力数值。 ③：这张卡被解放的场合，以自己场上1只表侧表示怪兽为对象才能发动。这个回合，那只怪兽在同1次的战斗阶段中可以作2次攻击。'),
(23701465, 'Primal Seed', '原初之种', '原初の種', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '「混沌战士 -开辟的使者-」或「混沌帝龙 -终焉的使者-」在场上存在的场合，这张卡才能发动。将自己2张从游戏中除外的卡加入自己手卡。'),
(85692042, 'Primathmech Alembertian', '块斩机达朗贝尔算子', '塊斬機ダランベルシアン', 'XYZ Monster', 'Cyberse', 'EARTH', 4, 2000, NULL, '4星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡超量召唤的场合，可以把这张卡的超量素材的以下数量取除，那个效果发动。 ●2：从卡组把1张「斩机」卡加入手卡。 ●3：从卡组把1只4星怪兽加入手卡。 ●4：从卡组把1张魔法·陷阱卡加入手卡。 ②：把自己场上1只怪兽解放才能发动。从自己的手卡·墓地把1只4星「斩机」怪兽特殊召唤。'),
(88021907, 'Primathmech Laplacian', '块斩机拉普拉斯算子', '塊斬機ラプラシアン', 'XYZ Monster', 'Cyberse', 'EARTH', 4, 2000, NULL, '4星怪兽×3 这个卡名的①的效果1回合只能使用1次。 ①：这张卡超量召唤成功的场合，可以把这张卡最多3个超量素材取除，从以下效果选择那个数量发动。 ●对方手卡随机选1张送去墓地。 ●选对方场上1只怪兽送去墓地。 ●选对方场上1张魔法·陷阱卡送去墓地。 ②：自己场上的「斩机」卡被效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(12298909, 'Prime Material Dragon', '物质龙', 'マテリアルドラゴン', 'Effect Monster', 'Dragon', 'LIGHT', 6, 2400, 2000, '只要这张卡在自己场上表侧表示存在，给与基本分伤害的效果变成基本分回复的效果。此外，持有「把场上的怪兽破坏的效果」的魔法·陷阱·效果怪兽的效果发动时，可以把1张手卡送去墓地让那个发动无效并破坏。'),
(1287123, 'Prime Material Falcon', '物质猎鹰', 'マテリアルファルコ', 'Effect Monster', 'Winged Beast', 'WIND', 5, 2200, 800, '持有「把场上的魔法·陷阱卡破坏的效果」的效果怪兽的效果发动时，可以把1张手卡送去墓地让那个发动无效并破坏。'),
(77103950, 'Primeval Planet Perlereino', '壹世坏・佩尔雷诺', '壱世壊＝ペルレイノ', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张，这个卡名的③的效果1回合只能使用1次。 ①：作为这张卡的发动时的效果处理，可以从卡组把1只「珠泪哀歌族」怪兽或者「维萨斯-斯塔弗罗斯特」加入手卡。 ②：自己场上的融合怪兽以及「珠泪哀歌族」怪兽的攻击力上升500。 ③：自己的场上·墓地的「珠泪哀歌族」怪兽回到卡组·额外卡组的场合，以场上1张卡为对象才能发动。那张卡破坏。'),
(49729312, 'Primineral Kongreat', '砾岩之灵长－凝土大金刚', '礫岩の霊長－コングレード', 'Effect Monster', 'Rock', 'EARTH', 8, 3000, 2000, '这张卡不能通常召唤，用卡的效果才能特殊召唤。 ①：从对方的手卡·卡组有怪兽被送去墓地的场合才能发动。这张卡从手卡里侧守备表示特殊召唤。 ②：这张卡反转的场合，以场上最多2张卡为对象才能发动。那些卡破坏。'),
(37021315, 'Primineral Mandstrong', '泥岩灵长-强壮泥岩山魈', '泥岩の霊長－マンドストロング', 'Effect Monster', 'Rock', 'EARTH', 8, 2000, 3000, '这个卡名的②的效果1回合只能使用1次。 ①：这张卡可以当作魔法卡使用从手卡到魔法与陷阱区域盖放。 ②：盖放的这张卡被对方的效果破坏送去墓地的回合的结束阶段才能发动。这张卡特殊召唤。那之后，可以从自己墓地选「泥岩灵长-强壮泥岩山魈」以外的1只怪兽加入手卡。');